/* The thread (Figma "Timeline"): message groups, change runs and history
   entries are its items, 12 apart; 4 at the top under the pinned setup band,
   16 at the sides and bottom. */
.message-list {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 4px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--surface-canvas);
}

/* Chat navigation: the header and configuration footer stay outside the
   scrolling content so both remain reachable in a short or narrow dock. */
.chat-content { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.chat-content[hidden] { display: none; }

/* A temporary task chat takes the current workspace; its conversation keeps a
   reading width. */
.app--printer-setup, .app--focused-chat {
  background: var(--surface-canvas);
