            std::filesystem::path(data_dir()) / "jusprin" / "projects");
        auto& project_host = m_agent_pane->web_view().host();
        project_host.set_restore_points_provider([this] {
            nlohmann::json points = nlohmann::json::array();
            if (!m_autosave)
                return points;
            // Keep the first model saved at a boundary: later model-only saves
            // with the same change sequence must not move its restore target.
            std::map<std::uint64_t, std::string> by_change;
            for (const auto& version : m_autosave->history())
                if (version.change_seq != 0)
                    by_change.emplace(version.change_seq, version.id);
            for (const auto& [seq, id] : by_change)
                points.push_back({{"changeSeq", seq}, {"versionId", id}});
            return points;
        });
        project_host.set_page_message_handler([this](const std::string& type, const nlohmann::json& payload) {
            if (type != Agent::Protocol::kShellAction || !payload.is_object() ||
                payload.value("action", std::string()) != "revert_to_here")
                return false;
            const std::string id = payload.value("versionId", std::string());
            const auto versions = m_autosave->history();
            const auto found = std::find_if(versions.begin(), versions.end(), [&id](const auto& version) {
                return version.id == id && version.change_seq != 0;
            });
            if (found == versions.end() || !m_autosave->restore(id)) {
                wxMessageBox(_L("This saved version couldn't be restored. Try again from Version history."),
                             _L("Revert failed"), wxOK | wxICON_ERROR, m_frame);
            }
            m_agent_pane->web_view().host().refresh_page_state();
            return true;
// What follows one conversation item: history cards and runs of changes, in
// seq order. Consecutive changes form one block, which draws as one group.
type TimelineBlock =
  | { kind: 'history'; seq: number; entry: ManufacturingHistoryEntry }
  | { kind: 'changes'; seq: number; changes: ChangeInfo[] };

function timeline(history: ManufacturingHistoryEntry[], changes: ChangeInfo[]): TimelineBlock[] {
  const items = [
    ...history.map((entry) => ({ seq: entry.seq, history: entry, change: undefined })),
    ...changes.map((change) => ({ seq: change.seq, history: undefined, change })),
  ].sort((a, b) => a.seq - b.seq);
  const blocks: TimelineBlock[] = [];
  for (const item of items) {
    const previous = blocks[blocks.length - 1];
    if (item.change && previous?.kind === 'changes') previous.changes.push(item.change);
    else if (item.change) blocks.push({ kind: 'changes', seq: item.seq, changes: [item.change] });
    else blocks.push({ kind: 'history', seq: item.seq, entry: item.history! });
  }
  return blocks;
}

function TimelineBlocks({ blocks, restorePoints, onRevert }: { blocks: TimelineBlock[]; restorePoints: RestorePointInfo[]; onRevert?: (versionId: string) => void }) {
  return (
    <>
      {blocks.map((block) =>
        block.kind === 'history' ? (
          <ManufacturingHistoryCard key={`${block.entry.kind}-${block.entry.record.id}`} entry={block.entry} />
        ) : (
          <ChangeRows key={`changes-${block.seq}`} changes={block.changes} restorePoints={restorePoints} onRevert={onRevert} />
        ),
      )}
    </>
  );
}

const inFlight = new Set(['pending', 'approved', 'running']);
  count: number;
}

// Consecutive entries merge when they are the same edit by the same actor:
// the same kind and label, which for a setting is the same setting. Eleven
// rotate steps are one row; a rotate then a move are two.
export function groupChanges(changes: ChangeInfo[], restorePoints: RestorePointInfo[] = []): ChangeRun[] {
  const runs: ChangeRun[] = [];
  const boundaries = new Set(restorePoints.map((point) => point.changeSeq));
  for (const change of [...changes].sort((a, b) => a.seq - b.seq)) {
    const run = runs[runs.length - 1];
    if (run && !boundaries.has(run.last.seq) && run.last.kind === change.kind && run.last.label === change.label && run.last.actor === change.actor) {
      run.last = change;
      run.count += 1;
    } else {
      runs.push({ first: change, last: change, count: 1 });
    }
  }
  return runs;
}

