// Consecutive entries merge when they are the same edit by the same actor:
// the same kind and label, which for a setting is the same setting. Eleven
// rotate steps are one row; a rotate then a move are two.
export function groupChanges(changes: ChangeInfo[], restorePoints: RestorePointInfo[] = []): ChangeRun[] {
  const runs: ChangeRun[] = [];
  const boundaries = new Set(restorePoints.map((point) => point.changeSeq));
  for (const change of [...changes].sort((a, b) => a.seq - b.seq)) {
    const run = runs[runs.length - 1];
    if (run && !boundaries.has(run.last.seq) && run.last.kind === change.kind && run.last.label === change.label && run.last.actor === change.actor) {
      run.last = change;
      run.count += 1;
    } else {
      runs.push({ first: change, last: change, count: 1 });
    }
  }
  return runs;
}

