ChangeEntry ProjectStateDocument::add_change(ChangeEntry entry, const std::string& timestamp)
{
    entry.conversation_id = active_conversation_id();
    entry.after_id        = last_item_id(entry.conversation_id);
    entry.seq             = next_seq();
    entry.created_at      = timestamp;
    json record{{"seq", entry.seq},
                {"createdAt", entry.created_at},
                {"kind", entry.kind},
                {"actor", entry.actor},
                {"label", entry.label},
                {"conversationId", entry.conversation_id},
                {"afterId", entry.after_id}};
    if (entry.kind == "setting") {
        record["from"]   = entry.from;
        record["to"]     = entry.to;
        record["preset"] = entry.preset;
    } else if (entry.kind == "restore") {
        // Keep the exact source and target versions in the audit entry.
        record["from"] = entry.from;
        record["to"]   = entry.to;
    }
    {
        std::uint64_t object_id{0};
        int backup_id{0};
        std::size_t facets{0};
        std::string entry;
        Resource resource;
    };

    struct Version
    {
        std::string id;
        std::uint64_t revision{0};
        // Last raw change included in this immutable model snapshot. Zero
        // means an older manifest without a known timeline boundary.
        std::uint64_t change_seq{0};
        std::string created_at;
        std::string source_path;
        std::vector<ObjectResource> objects;
        std::string project_name;
    };

      document.removeEventListener('keydown', escape);
    };
  }, [open]);

  return (
    <div className="change-rows" role="list" aria-label="Changes">
      {groupChanges(changes, restorePoints).map((run) => (
        <div key={run.first.seq} className="change-row" role="listitem" data-testid={`change-${run.first.seq}`}>
          <span className="change-icon" aria-hidden="true">✎</span>
          <div className="change-text">
            <span className="change-title">{title(run)}</span>
            <span className="change-meta">{meta(run)}</span>
          </div>
          {onRevert && points.has(run.last.seq) && (
            <span className="change-revert-action">
              <button type="button" className="change-revert-button" aria-label="Revert to here"
                aria-expanded={open === points.get(run.last.seq)}
                onClick={(event) => {
                  anchor.current = event.currentTarget;
                  setOpen(open === points.get(run.last.seq) ? null : points.get(run.last.seq)!);
                }}>
                <span className="change-revert-icon" aria-hidden="true" />
              </button>
              <span className="change-revert-tooltip" role="tooltip">Revert to here</span>
            </span>
          )}
        </div>
      ))}
      {open && createPortal(
        <div ref={popover} className="change-revert-popover" role="dialog" aria-label="Revert to here?"
          style={{ top: position.top, left: position.left }}>

