std::string ProjectAutosave::pin_current()
{
    if (!save_now())
        return {};
    // A blank startup draft has no automatic version, but it is still the
    // exact before-state of an Agent operation that may add its first object.
    if (m_store->head_id().empty()) {
        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
        if (canvas == nullptr || !canvas->is_initialized()) {
            fail("The project canvas is not ready for a durable save");
            return {};
        }
        if (!capture(true))
            return {};
    m_head_needs_sync = false;
}

ProjectVersionStore::Version ProjectVersionStore::read_version(const std::string& id) const
{
    require(safe_component(id), "invalid version id");
    Version version = parse_version(read_file(version_dir(id) / "manifest.json"));
    require(version.id == id, "version manifest id does not match directory");
    return version;
}

std::vector<ProjectVersionStore::Version> ProjectVersionStore::history() const
{
